"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[30832],{30832:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/b8f87dd641bc4ab23838b4b7247dec56.jpg\\"\\n  title=\\"Juchaek Gongsa\\"\\n  cuisine=\\"Bookstore\\"\\n  address=\\"36-11 Millakbondong-ro 19beon-gil, Suyeong-gu, Busan\\"\\n  rating=4\\n  tags=\\"spot\\"\\n/>\\n</center>\\n\\n## Review\\nI visited \'Juchaek Gongsa\', a charming independent bookstore located in Millak-dong, Suyeong-gu, Busan.\\n\\nThe most distinctive feature here is the <mark>Birthday Book Package</mark>.  \\nBased on the <mark>first edition publication date</mark>, they curate books released on the same month and day as your birthday (or the recipient\'s) and wrap them beautifully as blind books.  \\n\\nOnly the date is written on the wrapping, so you don\'t know which book is inside until you open it.  \\n\\nSince it offers the unique experience of meeting a book with the same birthday, I highly recommend it to anyone looking for a thoughtful and memorable gift for someone special.  \\n\\nEach recommended book comes with an introductory note handwritten by the owner, showing their special affection for books.  \\nThey also explain the meaning of the Birthday Book Package in detail when you purchase one.\\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/2dd15fbdd3553c1959f1b6776d7a95d6.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Juchaek Gongsa\\">\\n<img src=\\"/assets/snippets/location/acac8f5b04a7c73186588a2dc486824f.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Juchaek Gongsa\\">\\n<img src=\\"/assets/snippets/location/b83380c83752f4176d5802d4926faae0.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Juchaek Gongsa\\">\\n<img src=\\"/assets/snippets/location/42d83e91a09e94ccdf3c4ff13ae92c9f.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Juchaek Gongsa\\">\\n<img src=\\"/assets/snippets/location/22213c37d8da3073dde7d82877352f4b.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Juchaek Gongsa\\">\\n</pictures>\\n"}')}}]);